SELECT


WHERE a.status != #{deletedStatus}
ORDER BY a.show_order DESC, a.id ASC

SELECT COUNT(*) FROM tab_admin a
WHERE a.status != #{deletedStatus}
AND EXISTS (
    SELECT 1 FROM tab_user_position up
    WHERE up.user_id = a.user_id
    AND up.status != #{positionDeletedStatus}
    AND up.org_id = -1

        AND up.org_id IN
        #{orgId}

)
